function dump(node, depth=0) {
  if (depth>2) return;
  const pad = "  ".repeat(depth);
  let info = `${node.type} "${node.name}" id=${node.id}`;
  if (node.type==='COMPONENT' || node.type==='INSTANCE') info += ` comp=${node.componentId||''}`;
  console.log(pad+info);
  for (const c of node.children||[]) dump(c, depth+1);
}
