  const pad="  ".repeat(depth);
  let props = `fill=${node.fills && node.fills.length?JSON.stringify(node.fills.map(f=>({t:f.type,c:f.color?f.color:{}}))):'none'} `;
  if(node.type==='TEXT'){
    props += `char="${(node.characters||'').slice(0,30)}" fontName=${JSON.stringify(node.fontName)} fontSize=${node.fontSize}`;
