(async () => {
  const out = {makeText:null};

  const ws = figma.root.children.find(p => p.name.includes("Workspace"));
  await figma.setCurrentPageAsync(ws);
  const page = figma.currentPage;

  // Create local color styles (design tokens)
  const colors = {
    ink:"000000", surface:"FFFFFF", gray:"F5F5F6", gray2:"EDEDEF",
    border:"E4E4E7", text:"18181B", sub:"71717A", muted:"A1A1AA",
    star:"FFB800", red:"EF4444", accent:"2563EB"
  };
  const styleMap = {};
  let createdStyles = [];
  for (const [name,hex] of Object.entries(colors)) {
    const st = figma.createPaintStyle();
    st.name = "cyber/"+name;
    st.paints = [{type:"SOLID", color:{r:parseInt(hex.slice(0,2),16)/255,g:parseInt(hex.slice(2,4),16)/255,b:parseInt(hex.slice(4,6),16)/255}}];
    styleMap[name]=st;
    createdStyles.push(name);
  }
  out.styles = createdStyles;

  // Make reusable components

  // 1) BUTTON — build our own black button component
  const btn = figma.createComponent();
  btn.name = "cyber/Button";
  btn.resize(260,56);
  btn.fills=[{type:"SOLID",color:{r:0,g:0,b:0}}];
  const btnLabel = figma.createText();
  await figma.loadFontAsync({family:"Inter", style:"Semi Bold"});
  btnLabel.characters="Button";
  btnLabel.fontName={family:"Inter", style:"Semi Bold"};
  btnLabel.fontSize=16;
  btnLabel.fills=[{type:"SOLID",color:{r:1,g:1,b:1}}];
  btnLabel.x=(btn.width-btnLabel.width)/2;
  btnLabel.y=(btn.height-btnLabel.height)/2;
  btn.appendChild(btnLabel);
  btn.componentProperties = {}; // default
  out.button = btn.id;

  // 2) HEADER component
  const header = figma.createComponent();
  header.name = "cyber/Header";
  header.resize(1440,76);
  header.fills=[{type:"SOLID",color:{r:1,g:1,b:1}}];
  header.strokes=[{type:"SOLID",color:{r:0.894,g:0.894,b:0.898}}];
  header.strokeWeight={top:0,bottom:1,left:0,right:0}; // we'll just set

  // wordmark
  const mark = figma.createText();
  await figma.loadFontAsync({family:"Inter", style:"Extra Bold"});
  mark.characters="cyber";
  mark.fontName={family:"Inter", style:"Extra Bold"};
  mark.fontSize=26;
  mark.fills=[{type:"SOLID",color:{r:0,g:0,b:0}}];
  mark.x=64; mark.y=20;
  header.appendChild(mark);

  // nav items
  const navItems = ["Home","About","Contact Us","Blog"];
  const navParent = figma.createFrame();
  navParent.name="Nav";
  navParent.layoutMode="HORIZONTAL";
  navParent.primaryAxisAlign="MIN";
  navParent.counterAxisAlign="CENTER";
  navParent.itemSpacing=28;
  navParent.x=430; navParent.y=0; navParent.resize(400,76);
  navParent.fills=[];
  for(const it of navItems){
    const t=figma.createText();
    await figma.loadFontAsync({family:"Inter", style: it==="Home"?"Semi Bold":"Regular"});
    t.characters=it; t.fontName={family:"Inter", style: it==="Home"?"Semi Bold":"Regular"}; t.fontSize=15;
    t.fills=[{type:"SOLID",color:{r: it==="Home"?0:0.44,g: it==="Home"?0:0.44,b: it==="Home"?0:0.47}}];
    navParent.appendChild(t);
  }
  header.appendChild(navParent);

  // search field
  const search = figma.createFrame();
  search.name="Search"; search.x=600; search.y=16; search.resize(260,44);
  search.fills=[{type:"SOLID",color:{r:0.961,g:0.961,b:0.965}}];
  search.cornerRadius=8;
  const sTxt=figma.createText();
  await figma.loadFontAsync({family:"Inter", style:"Regular"});
  sTxt.characters="Search"; sTxt.fontName={family:"Inter",style:"Regular"}; sTxt.fontSize=14;
  sTxt.fills=[{type:"SOLID",color:{r:0.63,g:0.63,b:0.64}}];
  sTxt.x=16; sTxt.y=13; search.appendChild(sTxt);
  header.appendChild(search);

  // icons group (wishlist, cart, user) via media instances
  const iconIds = {wishlist:"1:209", cart:"1:194", user:"1:224"};
  const iconPos = {wishlist:960, cart:1008, user:1056};
  for(const [k,id] of Object.entries(iconIds)){
    const inst = figma.createInstanceFromNodeId(id);
    inst.name=k;
    inst.x=iconPos[k]; inst.y=22;
    inst.rescale(32,32);
    header.appendChild(inst);
  }
  header.x=0; header.y=0;
  header.layoutMode="NONE";
  out.header = header.id;
  out.headerMark = mark.id;

  figma.currentPage.appendChild(header);
  header.y=0; 
  const res = {header:header.id, button:btn.id};
  return out;
})().catch(e=>JSON.stringify({err:e.message}))

