  header.appendChild(mkText("Home", 600, 35, 15, "Medium", C.black));
  header.appendChild(mkText("About", 662, 35, 15, "Regular", C.text));
  header.appendChild(mkText("Contact Us", 724, 35, 15, "Regular", C.text));
  header.appendChild(mkText("Blog", 824, 35, 15, "Regular", C.text));

  // Icons (placeholders via simple boxes as markers)
  function iconBox(x,name){
    const r = figma.createRectangle(); r.resize(32,32); r.x=x; r.y=28; r.fills=[{type:"SOLID",color:hex(C.grayBg)}]; r.cornerRadius=6; r.name=name; header.appendChild(r); return r;
  }
  iconBox(1150,"Icon_Heart_holder");
  iconBox(1200,"Icon_Cart_holder");
  iconBox(1250,"Icon_User_holder");

