  // robust media finder
  function getM(name){
    function f(node){
      if(node.type==='COMPONENT' && node.name===name) return node;
      for(const c of node.children||[]){ const r=f(c); if(r) return r; }
      return null;
    }
    return f(mediaPage);
  }
  const btnComp = (function(){function f(n){if(n.type==='COMPONENT'&&n.name==='cyber/Button')return n;for(const c of n.children||[]){const r=f(c);if(r)return r;}return null;}return f(ws);})();

  const fonts = [{family:"Inter",style:"Regular"},{family:"Inter",style:"Medium"},{family:"Inter",style:"Semi Bold"},{family:"Inter",style:"Bold"}];
  for(const ft of fonts){ try{ await figma.loadFontAsync(ft);}catch(e){} }

  function addText(str,x,y,size,weight,color,parent,w){
    try{
      const styleName = weight==='sb'?'Semi Bold':(weight==='b'?'Bold':(weight==='m'?'Medium':'Regular'));
      const t = figma.createText();
      t.characters=str;
      t.fontName={family:"Inter",style:styleName};
      t.fontSize=size;
      t.fills=[{type:'SOLID',color:color}];
      t.x=x; t.y=y;
      if(w) t.resize(w, t.height);
      (parent||home).appendChild(t);
      return t;
