      inst.x=x; inst.y=y; inst.resize(w,h);
      (parent||home).appendChild(inst);
      // recolor: ensure black bg on the instance's main frame
      if(inst.fills && inst.fills.length){ inst.fills=[{type:'SOLID',color:{r:0,g:0,b:0}}]; }
      const lab = inst.findOne(n=>n.type==='TEXT');
      if(lab){ lab.characters=label; }
      return inst;
    }catch(e){ report.err.push('btn '+label+':'+e.message); return null;}
  }
